package com.library.repository;

import java.util.List;
import java.util.Optional;

import org.springframework.data.jpa.repository.JpaRepository;

import com.library.domain.Book;

/**
 * Data access for {@link Book}. Every method body is generated by Spring Data
 * from the method name — there is nothing to implement here.
 */
public interface BookRepository extends JpaRepository<Book, Long> {

    boolean existsByIsbn(String isbn);

    Optional<Book> findByIsbn(String isbn);

    List<Book> findByCategoryIgnoreCase(String category);

    /**
     * The catalog search box: match title or author, case-insensitively.
     * Both parameters receive the same search string.
     */
    List<Book> findByTitleContainingIgnoreCaseOrAuthorContainingIgnoreCase(String title, String author);
}
